pub assume_specification<T, E>[Result::<Option<T>, E>::transpose](
    result: Result<Option<T>, E>,
) -> (res: Option<Result<T, E>>)
    ensures
        res == (match result {
            Result::Ok(Option::Some(value)) => Option::Some(Result::Ok(value)),
            Result::Ok(Option::None) => Option::None,
            Result::Err(error) => Option::Some(Result::Err(error)),
        }),
;

pub assume_specification<T, E>[Result::<T, E>::unwrap_or](
    result: Result<T, E>,
    default: T,
) -> (res: T)
    ensures
        res == (match result {
            Result::Ok(value) => value,
            Result::Err(_) => default,
        }),
;
